/* Query or expand a bounded guarded A8 page through pocket-glyph-pages. max_dimension is a power of two in 8..4096. Null pixels with zero capacity queries metadata only; otherwise capacity must cover width*height. Errors leave pixels and out unchanged. Font, output bytes and metadata must not overlap. */
int32_t pocket_glyph_page_a8(const pocket_font_view * font, uint32_t glyph, uint32_t max_dimension, uint8_t * pixels, size_t capacity, pocket_glyph_page * out);

/* Create a thread-owned monotonic deadline schedule. Invalid rate, zero lag limit, or overflow returns null. Platform code owns waits and cancellation. */
pocket_tick_schedule * pocket_tick_schedule_create(uint32_t tick_hz, uint64_t started, uint64_t max_lag_us);

int32_t pocket_tick_schedule_deadline(const pocket_tick_schedule * schedule, uint64_t * out);

/* Reserve at most one due slot. Early polls set ready to zero without advancing; excessive lag skips expired wall-clock slots. Invalid output prefixes leave the schedule unchanged. */
int32_t pocket_tick_schedule_poll(pocket_tick_schedule * schedule, uint64_t now, pocket_tick_timing * out, uint32_t * ready);

void pocket_tick_schedule_destroy(pocket_tick_schedule * schedule);

pocket_runtime * pocket_runtime_create(const pocket_runtime_config * config);

int32_t pocket_runtime_set_package_source(pocket_runtime * runtime, const pocket_package_source_v1 * source, void * context);

int32_t pocket_runtime_set_guest(pocket_runtime * runtime, const pocket_guest_v1 * guest, void * context);

/* Decoded bytes of package textures the runtime keeps past a frame; zero, the default, keeps every texture. Beyond it, when a frame is drawn, textures the previous frame did not draw are released, least recently drawn first, and decoded from the package again by the next frame that draws them. Textures a deferred submission still reads stay. */
int32_t pocket_runtime_set_texture_budget(pocket_runtime * runtime, size_t bytes);

pocket_renderer_id pocket_runtime_add_renderer(pocket_runtime * runtime, const pocket_renderer_v1 * renderer, void * context);

int32_t pocket_runtime_add_display(pocket_runtime * runtime, const pocket_display_output_v1 * display, void * context, pocket_renderer_id renderer);

int32_t pocket_runtime_add_input_source(pocket_runtime * runtime, const pocket_input_source_v1 * source, void * context);

int32_t pocket_runtime_add_op_provider(pocket_runtime * runtime, const pocket_op_provider_v1 * provider, void * context, const uint16_t * operations, size_t operation_count);

int32_t pocket_runtime_boot(pocket_runtime * runtime);

/* Admit and evaluate the package without presenting it. The program calls pocket_runtime_present before the first tick, after its native scene or host overlay is ready. */
int32_t pocket_runtime_boot_deferred(pocket_runtime * runtime);

/* Present the retained tree without running the guest: after boot_deferred, to retry a failed output, or to redraw it under a host overlay. A guest that failed keeps its last tree presentable; advancing it stays rejected. */
int32_t pocket_runtime_present(pocket_runtime * runtime);

/* Complete in-flight DEFERRED frames: renderer wait, flush or display wait, retire. Returns zero when none is pending. A failed completion returns its error once and invalidates that display's damage history. Call before reading a presented buffer or releasing state a pending submission reads. */
int32_t pocket_runtime_complete_presentation(pocket_runtime * runtime);

/* Sample inputs, run the guest frame once, advance the core by the booted package's core_ticks, and present. */
int32_t pocket_runtime_tick(pocket_runtime * runtime);

/* After boot, the package rate and the cadence the program schedules pocket_runtime_tick at. INVALID before boot. */
int32_t pocket_runtime_get_timing(const pocket_runtime * runtime, pocket_runtime_timing * out);

/* Returns 0 or 1 without executing the operation. Does not invalidate borrowed results. */
uint32_t pocket_runtime_supports_op(const pocket_runtime * runtime, uint16_t op);

/* Generated bindings use this operation dispatcher. out bytes expire at the next call on runtime. */
int32_t pocket_runtime_op(pocket_runtime * runtime, uint16_t op, const void * args, size_t length, pocket_result * out);

/* Overwrite the rectangle of a live 16- or 32-bit texture in place with width*height texels in its format, rows packed: the handle and the nodes drawing it stay, and the next frame repaints only the quads that sample it. Not during a guest callback; INVALID for a stale handle, an indexed texture, a rectangle outside the texture or another byte count. */
int32_t pocket_runtime_update_texture(pocket_runtime * runtime, int32_t handle, uint32_t x, uint32_t y, uint32_t width, uint32_t height, const uint8_t * pixels, size_t length);

void pocket_runtime_destroy(pocket_runtime * runtime);

/* Software fallback after accelerator completion and cache visibility, within target's acquired region. */
int32_t pocket_raster_draw_op(pocket_surface * target, const pocket_draw_op * op, const pocket_render_resources * resources);

/* Validate the complete matching-version DrawList before any callback, then visit every operation in order with inherited logical clip and positive output scale. Callback errors stop iteration and are returned unchanged. No allocation or resource lookup occurs. */
int32_t pocket_draw_list_visit(const pocket_draw_list * list, const pocket_render_resources * resources, uint32_t scale, pocket_draw_op_visit_fn visitor, void * context);

void * pocket_host_alloc(size_t size, size_t align);

/* On allocation failure return null and preserve the original allocation. */
void * pocket_host_realloc(void * pointer, size_t old_size, size_t align, size_t new_size);

void pocket_host_free(void * pointer, size_t size, size_t align);

/* Fatal runtime failure; the program must not return from this hook. */
void pocket_host_panic(const char * message, size_t length);

void pocket_host_log(int32_t level, const char * message, size_t length);

void pocket_host_boot_stage(int32_t stage);

